{"provenance":"deterministic","nodes":[{"name":"SanitizeInstance","kind":"function","path":"entityid/entityid.go","lines":[318,347],"body":"func SanitizeInstance(s string) string {
	var b strings.Builder
	b.Grow(len(s))
	for _, r := range s {
		if isAllowedInstanceRune(r) {
			b.WriteRune(r)
		} else {
			b.WriteRune('-')
		}
	}
	out := b.String()
	for strings.Contains(out, "--") {
		out = strings.ReplaceAll(out, "--", "-")
	}
	out = strings.TrimFunc(out, func(r rune) bool { return !isASCIIAlnum(r) })

	if out == "" {
		return shortHash(s)
	}
	if len(out) > maxInstanceLen {
		suffix := shortHash(s)
		prefix := strings.TrimRightFunc(out[:maxInstanceLen-len(suffix)-1],
			func(r rune) bool { return !isASCIIAlnum(r) })
		if prefix == "" {
			return suffix
		}
		return prefix + "-" + suffix
	}
	return out
}","relations":{"callee":[{"name":"isASCIIAlnum","path":"entityid/entityid.go","line":387},{"name":"isAllowedInstanceRune","path":"entityid/entityid.go","line":383},{"name":"shortHash","path":"entityid/entityid.go","line":391}],"caller":[{"name":"TestSanitizeInstance","path":"entityid/entityid_test.go","line":255},{"name":"TestSanitizeInstance_DeterministicForSameInput","path":"entityid/entityid_test.go","line":304},{"name":"TestSanitizeInstance_FallbackHash","path":"entityid/entityid_test.go","line":292},{"name":"TestSanitizeInstance_LengthCapPreservesUniqueness","path":"entityid/entityid_test.go","line":313},{"name":"DocumentEntityID","path":"handler/doc/entities.go","line":85},{"name":"chunkInstance","path":"handler/doc/entities.go","line":139},{"name":"BuildAuthorEntity","path":"handler/git/entities.go","line":37},{"name":"BuildBranchEntity","path":"handler/git/entities.go","line":57},{"name":"newAuthorEntity","path":"handler/git/entities.go","line":171},{"name":"newBranchEntity","path":"handler/git/entities.go","line":213},{"name":"Triples","path":"handler/git/entities.go","line":113}],"container":[{"name":"entityid.go","path":"entityid/entityid.go","line":1}]},"class":"https://www.commoncoreontologies.org/ont00000653","handle":"acme.semsource-a92ca8.workspace.golang.function.entityid-entityid-go-SanitizeInstance"}],"impact":{"nodes":20,"files":7,"truncated":false},"truncated":false,"contract_version":"2"}

