	name := spec2.ChildByFieldName("name")
	alias := spec2.ChildByFieldName("alias")
	if name == nil {
		// Grammar exposes name/alias as positional identifiers on some versions.
		var ids []*sitter.Node
		for k := 0; k < int(spec2.NamedChildCount()); k++ {
			if spec2.NamedChild(k).Type() == "identifier" {
				ids = append(ids, spec2.NamedChild(k))
			}
		}
		if len(ids) == 0 {
			return
		}
		origin := nodeText(ids[0], source)
		local := origin
		if len(ids) > 1 {
			local = nodeText(ids[1], source)
		}
		bindings[local] = tsBinding{spec: spec, origin: origin}
		return
	}
	origin := nodeText(name, source)
	local := origin
	if alias != nil {
		local = nodeText(alias, source)
	}
	bindings[local] = tsBinding{spec: spec, origin: origin}
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"acme.semsource-a92ca8.workspace.golang.function.source-ast-ts-imports-go-addNamedImport"},{"name":"workbench.test.ts","kind":"file","path":"ui/src/lib/api/workbench.test.ts","lines":[1,172],"class":"https://www.commoncoreontologies.org/ont00000798","handle":"acme.semsource-a92ca8.workspace.typescript.file.ui-src-lib-api-workbench-test-ts"},{"name":"workbench.ts","kind":"file","path":"ui/src/lib/api/workbench.ts","lines":[1,151],"class":"https://www.commoncoreontologies.org/ont00000798","handle":"acme.semsource-a92ca8.workspace.typescript.file.ui-src-lib-api-workbench-ts"},{"name":"workbench_capabilities.go","kind":"file","path":"processor/source-manifest/workbench_capabilities.go","lines":[1,408],"class":"https://www.commoncoreontologies.org/ont00000798","handle":"acme.semsource-a92ca8.workspace.golang.file.processor-source-manifest-workbench_capabilities-go"},{"name":"workbench_capabilities_test.go","kind":"file","path":"processor/source-manifest/workbench_capabilities_test.go","lines":[1,517],"class":"https://www.commoncoreontologies.org/ont00000798","handle":"acme.semsource-a92ca8.workspace.golang.file.processor-source-manifest-workbench_capabilities_test-go"},{"name":"Description","kind":"method","path":"cli/wizard_doc.go","lines":[17,17],"body":"func (w *docWizard) Description() string       { return "markdown, text files" }","class":"https://www.commoncoreontologies.org/ont00000653","handle":"acme.semsource-a92ca8.workspace.golang.method.cli-wizard_doc-go-docWizard-Description"},{"name":"UnresolvedMarkerKind","kind":"type","path":"ui/src/lib/graph/drilldown.ts","lines":[3,3],"body":"export type UnresolvedMarkerKind = "builtin" | "external" | "unhydrated";","class":"https://www.commoncoreontologies.org/ont00000965","handle":"acme.semsource-a92ca8.workspace.typescript.type.ui-src-lib-graph-drilldown-ts-UnresolvedMarkerKind"},{"name":"settlementPublisher","kind":"struct","path":"internal/enti