	var s Supervisor
	var mu sync.Mutex
	finished := false

	started := make(chan struct{})
	s.Start(context.Background(), nil, func(ctx context.Context) error {
		close(started)
		<-ctx.Done()
		time.Sleep(50 * time.Millisecond) // unwinding after cancellation
		mu.Lock()
		finished = true
		mu.Unlock()
		return ctx.Err()
	})
	<-started

	stopCtx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	s.Stop(stopCtx, nil)

	mu.Lock()
	defer mu.Unlock()
	if !finished {
		t.Error("Stop() returned before the seed finished unwinding")
	}
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"acme.semsource-a92ca8.workspace.golang.function.internal-seedsup-supervisor_test-go-TestStopWaitsForTheSeed"},{"name":"TestWorstCaseSegmentsLeaveInstanceBudget","kind":"function","path":"entityid/entityid_test.go","lines":[481,496],"body":"func TestWorstCaseSegmentsLeaveInstanceBudget(t *testing.T) {
