{"provenance":"deterministic","nodes":[{"name":"URLToSlug","kind":"function","path":"workspace/workspace.go","lines":[162,182],"body":"func URLToSlug(rawURL string) string {
	// Handle SSH shorthand: git@github.com:owner/repo.git → github.com/owner/repo.git
	if strings.HasPrefix(rawURL, "git@") {
		rawURL = strings.TrimPrefix(rawURL, "git@")
		rawURL = strings.Replace(rawURL, ":", "/", 1)
	}

	// Strip .git suffix before any further processing so it is removed
	// regardless of which parse path we take below.
	rawURL = strings.TrimSuffix(rawURL, ".git")

	// Parse as URL to extract host + path.
	parsed, err := url.Parse(rawURL)
	if err != nil || parsed.Host == "" {
		// Fallback: just slugify the whole string.
		return slugify(rawURL)
	}

	combined := parsed.Host + parsed.Path
	return slugify(combined)
}","relations":{"callee":[{"name":"slugify","path":"workspace/workspace.go","line":468}],"caller":[{"name":"startSubmoduleWatchers","path":"cmd/semsource/run.go","line":1099},{"name":"expandMultiBranch","path":"config/expand.go","line":154},{"name":"expandSingleBranch","path":"config/expand.go","line":92},{"name":"TestTick_ExpandsDualPinWithCanonicalIdentityAndScopedInstances","path":"internal/subwatch/subwatch_test.go","line":116},{"name":"EnsureRepo","path":"workspace/workspace.go","line":36},{"name":"TestURLToSlug","path":"workspace/workspace_test.go","line":12},{"name":"systemSlug","path":"handler/git/handler.go","line":398},{"name":"Tick","path":"internal/subwatch/subwatch.go","line":123},{"name":"spawn","path":"internal/subwatch/subwatch.go","line":202}],"container":[{"name":"workspace.go","path":"workspace/workspace.go","line":1}]},"class":"https://www.commoncoreontologies.org/ont00000653","handle":"acme.semsource-a92ca8.workspace.golang.function.workspace-workspace-go-URLToSlug"}],"impact":{"nodes":77,"files":26,"truncated":false},"truncated":false,"contract_version":"2"}
